private static List<BigDecimal> curtailTargets(List<AllocationRow> approved, int essentialPct,
                                               int normalPct, int deferrablePct) {
    List<BigDecimal> targets = new ArrayList<>(approved.size());
    for (AllocationRow a : approved) {
        targets.add(curtailTarget(a.baseHeldAmount(), pctOf(a.priority(), essentialPct, normalPct, deferrablePct)));
    }
    for (String priority : PRIORITIES) {
        int pct = pctOf(priority, essentialPct, normalPct, deferrablePct);
        BigDecimal levelBase = BigDecimal.ZERO;
        BigDecimal sumTargets = BigDecimal.ZERO;
        int first = -1;
        for (int i = 0; i < approved.size(); i++) {
            if (!priority.equals(approved.get(i).priority())) continue;
            if (first < 0) first = i;
            levelBase = levelBase.add(approved.get(i).baseHeldAmount());
            sumTargets = sumTargets.add(targets.get(i));
        }
        if (first < 0) continue;
        BigDecimal levelTarget = curtailTarget(levelBase, pct);
        BigDecimal delta = levelTarget.subtract(sumTargets);
        if (delta.signum() != 0) {
            targets.set(first, targets.get(first).add(delta));
        }
    }
    return targets;
}
